// @ts-check
'use strict';
// Go file rules (docs/MULTI_LANGUAGE_PLAN.md, G1): which files Go analyses, which are
// tests and which are generated. They follow the go tool's own conventions, so the
// answers match what `go build` and `go test` consider.

// The go tool ignores `testdata` directories, and `vendor` holds other modules' code: not
// the change under review. Matched against repository-relative paths.
const IGNORED_DIR = /(^|\/)(testdata|vendor)\//;
// Generated by name: protocol buffers and the common generator suffixes.
const GENERATED_NAME = /(\.pb\.go|\.pb\.gw\.go|_gen\.go|_generated\.go)$|(^|\/)zz_generated[^/]*\.go$/;
// The go tool's own rule (https://go.dev/s/generatedcode): a line, before the package
// clause, that matches exactly this.
const GENERATED_COMMENT = /^\/\/ Code generated .* DO NOT EDIT\.$/;
// How much of a file's head is read for that comment. The comment precedes the package
// clause, so it sits in the first lines; a file whose head is longer than this is read
// only this far, and its comment, if later, is missed (it is then analysed).
const GENERATED_HEAD_CHARS = 8192;

/** @param {string} relPath @returns {string} */
const slashed = (relPath) => String(relPath).replace(/\\/g, '/');

/**
 * Whether a file's text carries the go tool's generated-code comment before its package
 * clause.
 * @param {string} text The file's text.
 */
function hasGeneratedComment(text) {
  for (const line of text.slice(0, GENERATED_HEAD_CHARS).split('\n')) {
    const trimmed = line.replace(/\r$/, '');
    if (GENERATED_COMMENT.test(trimmed)) return true;
    if (/^\s*package\s/.test(trimmed)) return false;
  }
  return false;
}

/** @type {import('../types').LanguageFileRules} */
const goRules = Object.freeze({
  id: 'go',
  displayName: 'Go',
  handles: (relPath) => /\.go$/.test(relPath) && !IGNORED_DIR.test(slashed(relPath)),
  isTest: (relPath) => /_test\.go$/.test(relPath),
  isGenerated: (relPath, text) => GENERATED_NAME.test(slashed(relPath)) || hasGeneratedComment(text),
});

module.exports = { goRules, GENERATED_HEAD_CHARS };
